import random, re, sys
sys.path.insert(0, '/workspace/project/src')
from eywa.regex import compile_pattern

def to_python(node):
    """Translate the toolkit pattern AST into an equivalent Python regex."""
    cls = node.__class__.__name__
    if cls == "Empty":
        return ""
    if cls == "Range":
        low, high = node.low, node.high
        if low == high:
            return re.escape(low)
        return "[%s-%s]" % (re.escape(low), re.escape(high))
    if cls == "Choice":
        return "(" + "|".join(to_python(sub) for sub in node.exprs) + ")"
    if cls == "Seq":
        return "".join(to_python(sub) for sub in node.exprs)
    if cls == "Star":
        return "(" + to_python(node.expr) + ")*"
    raise AssertionError(cls)

def random_pattern(rng, depth=0):
    """Build a random pattern plus its source text and Python equivalent."""
    choice = rng.randint(0, 5 if depth < 3 else 2)
    if choice == 0:                                   # literal
        char = rng.choice("abc.*[]()|\\-")
        src = "\\" + char if char in ".*[]()|\\" else char
        return src, re.escape(char)
    if choice == 1:                                   # class
        items = []
        for _ in range(rng.randint(1, 3)):
            if rng.random() < 0.4:
                low, high = sorted(rng.sample(list("abcxyz"), 2))
                if rng.random() < 0.5:
                    items.append(re.escape(low) + "-" + re.escape(high))
                else:
                    items.append(re.escape(low))
            else:
                items.append(re.escape(rng.choice("abcxyz")))
        return "[" + "".join(items) + "]", "[" + "".join(items) + "]"
    if choice == 2:                                   # nullable / empty sequence
        return "", ""
    if choice == 3:                                   # union
        parts = [random_pattern(rng, depth + 1) for _ in range(rng.randint(2, 3))]
        return "(" + "|".join(p[0] for p in parts) + ")", "(" + "|".join(p[1] for p in parts) + ")"
    if choice == 4:                                   # sequence
        parts = [random_pattern(rng, depth + 1) for _ in range(rng.randint(1, 3))]
        return "".join(p[0] for p in parts), "".join(p[1] for p in parts)
    inner = random_pattern(rng, depth + 1)            # star
    return "(" + inner[0] + ")*", "(" + inner[1] + ")*"

rng = random.Random(99)
alphabet = ["a", "b", "c", "x", ".", "\\", "[", "]", "(", ")", "|", "*", "-"]
mismatches = 0
for trial in range(3000):
    src, python = random_pattern(rng)
    if len(src) > 128:
        continue
    try:
        mine = compile_pattern(src)
    except Exception as exc:
        print("parse error", repr(src), exc)
        mismatches += 1
        continue
    reference = re.compile("(?s:" + python + ")\\Z")
    for _ in range(12):
        text = "".join(rng.choice(alphabet) for _ in range(rng.randint(0, 6)))
        want = reference.match(text) is not None
        got = mine.matches(text)
        if got != want:
            print("MISMATCH", repr(src), repr(python), repr(text), got, want)
            mismatches += 1
            if mismatches > 5:
                sys.exit(1)
print("PASS regex differential (%d mismatches)" % mismatches)
